package app.masroufy.core

/** بنك النصايح الموثّقة — الجزء 2 من 3 (متولّد بـ`gen-tips.js`؛ شوف [VERIFIED_TIPS]). بيانات بس. */
internal val VERIFIED_TIPS_2: List<BankTip> = listOf(
    BankTip(
        "early-settlement-right", "sa", "none", TipGroup.DEBT,
        sa = TipWords("من حقك السداد المبكر للتمويل", "عند حصولك على مبلغ مقطوع (مكافأة، بدل إجازة، هدية) يمكنك سداد جزء من التمويل أو كامله مبكرًا. وفق القواعد في المملكة يسقط ربح المدة المتبقية، ولا يتجاوز تعويض الجهة الممولة عادةً تكلفة ثلاثة أشهر على الرصيد المتناقص. وتوجد استثناءات، منها عقود التمويل العقاري وبعض المبالغ الموثقة المدفوعة لأطراف أخرى، فاطلب من بنكك مبلغ السداد المبكر الدقيق قبل أن تقرر.", "يظن كثير من المقترضين أن السداد المبكر يكلّف كامل الربح المتبقي، فلا يستخدمون الفائض لتقليص الدين."),
        eg = TipWords("من حقك تسدّد التمويل بدري", "لما يجيلك مبلغ مرة واحدة (مكافأة، بدل إجازة، هدية)، تقدر تسدّد جزء من التمويل أو كله بدري. حسب القواعد في السعودية، ربح المدة الباقية بيسقط، وتعويض الجهة الممولة محدود وما يزيدش في العادة عن تكلفة 3 شهور على الرصيد المتبقي. فيه استثناءات، زي عقود التمويل العقاري وبعض المصاريف الموثقة اللي اتدفعت لجهات تانية، فاطلب من البنك مبلغ السداد المبكر بالظبط قبل ما تقرر.", "ناس كتير فاكرين إن السداد المبكر بيكلّف كل الربح الباقي، فما بيستخدموش الفلوس الزيادة عشان يقللوا الدين."),
        source = TipSource("البنك المركزي السعودي — دليل القواعد: دليل احتساب مبلغ السداد المبكر", "https://rulebook.sama.gov.sa/en/early-repayment", "2026-10-16"),
    ),
    BankTip(
        "ten-day-withdrawal", "sa", "none", TipGroup.DEBT,
        sa = TipWords("عدلت عن تمويل جديد؟ لديك 10 أيام", "إذا وقّعت عقد تمويل استهلاكي جديد ثم ندمت، تتيح لك القواعد في المملكة الانسحاب خلال 10 أيام من التوقيع. ويبقى هذا الحق قائمًا ما دمت لم تستخدم التمويل: لم تسحب نقدًا ولم تستخدم السلعة الممولة. أعد قراءة العقد والتكاليف قبل سحب أي مبلغ.", "كثيرًا ما يُدفع المدينون إلى تمويل جديد أو إضافي على عجل، ومعرفة وجود مخرج قصير تقلل الأخطاء المكلفة."),
        eg = TipWords("غيّرت رأيك في تمويل جديد؟ قدامك 10 أيام", "لو مضيت عقد تمويل استهلاكي جديد وندمت، القواعد في السعودية بتسمحلك تنسحب خلال 10 أيام من التوقيع. الحق ده قايم بس طول ما ما استخدمتش التمويل: ما سحبتش فلوس وما استخدمتش الحاجة اللي اتمولت. اقرا العقد والتكاليف تاني قبل ما تسحب أي مبلغ.", "اللي عليه ديون كتير بيتزق لقرض جديد أو زيادة بسرعة، ومعرفة إن فيه مخرج قصير بتقلل الغلطات الغالية."),
        source = TipSource("البنك المركزي السعودي — دليل القواعد: إيضاح المادتين 10 و21 من اللائحة المحدثة لنظام التمويل الاستهلاكي (2017)", "https://rulebook.sama.gov.sa/en/clarifying-article-no-10-and-article-no-21-including-method-calculating-annual-percentage-rate", "2026-10-16"),
    ),
    BankTip(
        "compare-annual-rate", "sa", "low", TipGroup.DEBT,
        sa = TipWords("قارن معدل النسبة السنوي لا القسط الشهري وحده", "عند المقارنة بين عروض التمويل، أو إعادة تمويل تجمع ديونك في دين واحد، انظر إلى معدل النسبة السنوي؛ فهو يبيّن التكلفة السنوية الكاملة شاملة الرسوم. وقد يكلفك قسط أقل على مدة أطول مبلغًا إجماليًا أكبر.", "كثيرًا ما تُسوّق عروض إعادة التمويل وتجميع الديون بقسط أصغر بينما ترتفع التكلفة الإجمالية."),
        eg = TipWords("قارن معدل النسبة السنوي، مش القسط الشهري بس", "لما تقارن عروض التمويل، أو إعادة تمويل بتجمع ديونك في دين واحد، بص على معدل النسبة السنوي. ده بيوضح التكلفة السنوية كاملة بالرسوم. القسط الأقل على مدة أطول ممكن يكلفك أكتر في الإجمالي.", "عروض إعادة التمويل وتجميع الديون بتتباع غالبًا بقسط أصغر، والتكلفة الإجمالية بتزيد."),
        source = TipSource("البنك المركزي السعودي — إصدار قواعد احتساب معدل النسبة السنوي", "https://www.sama.gov.sa/en-US/MediaCenter/News/pages/news-992.aspx", "2026-10-16"),
    ),
    BankTip(
        "lower-inflation-still-rising-prices", "eg", "none", TipGroup.SPREAD,
        sa = TipWords("انخفاض التضخم لا يعني انخفاض الأسعار", "عندما ينخفض معدل التضخم الرسمي تظل الأسعار ترتفع ولكن بوتيرة أبطأ. خطّط لميزانية الشهر القادم متوقعًا ارتفاع تكاليفك المعتادة، وقارن سرعة نمو بنود إنفاقك بالمعدل الرسمي لا بعناوين أخبار الشهر الماضي.", "قد يبعث خبر «انخفاض» التضخم طمأنينة زائفة. وتُقاس أي زيادة في الراتب بإجمالي ارتفاع الأسعار منذ آخر زيادة، ويمكن للتطبيق أن يعرض ارتفاع أسعارك أنت حسب التصنيف."),
        eg = TipWords("التضخم لما يقل، الأسعار برضه بتزيد", "لما معدل التضخم الرسمي يقل، الأسعار لسه بتزيد بس بسرعة أقل. خطط ميزانية الشهر الجاي على إن مصاريفك المعتادة هتزيد، وقارن سرعة زيادة بنود مصروفك انت بالمعدل الرسمي، مش بعنوان أخبار الشهر اللي فات.", "خبر إن التضخم «بينزل» ممكن يطمّنك على الفاضي. أي زيادة في المرتب تتقاس على إجمالي زيادة الأسعار من آخر زيادة، والتطبيق يقدر يوريك زيادة أسعارك انت حسب التصنيف."),
        source = TipSource("البنك المركزي المصري — ما هو التضخم؟", "https://www.cbe.org.eg/en/monetary-policy/inflation/what-is-inflation", "2026-10-16"),
    ),
    BankTip(
        "idle-cash-loses-value", "both", "low", TipGroup.SPREAD,
        sa = TipWords("النقد المعطّل يفقد قوته الشرائية بصمت", "النقد في مأمن من تقلبات السوق لكنه ليس في مأمن من التضخم. إذا ارتفعت الأسعار أسرع من نمو أموالك فإن المبلغ نفسه يشتري أقل كل عام. خصّص النقد للاحتياجات القريبة وصندوق الطوارئ، وتعرّف على الخيارات الأخرى للأهداف البعيدة قبل تحريك أي مبلغ.", "في فترات التضخم المرتفع قد تفقد الأموال المعطلة لسنوات جزءًا كبيرًا من قيمتها الحقيقية دون أن ينتبه صاحبها."),
        eg = TipWords("الكاش المركون بيخسر قيمته بهدوء", "الكاش في أمان من تقلبات السوق بس مش في أمان من التضخم. لو الأسعار بتزيد أسرع من فلوسك، نفس المبلغ بيشتري أقل كل سنة. خلّي الكاش للاحتياجات القريبة وصندوق الطوارئ، واتعلّم عن الاختيارات التانية للأهداف البعيدة قبل ما تحرك أي فلوس.", "في فترات التضخم العالي، الفلوس المركونة لسنين ممكن تخسر جزء كبير من قيمتها الحقيقية من غير ما صاحبها ياخد باله."),
        source = TipSource("هيئة الأوراق المالية الأمريكية (موقع توعية المستثمر) — دليل المبتدئين في توزيع الأصول والتنويع وإعادة التوازن", "https://www.investor.gov/additional-resources/general-resources/publications-research/info-sheets/beginners-guide-asset", "2026-10-16"),
    ),
    BankTip(
        "eg-gold-funds-licensed", "eg", "high", TipGroup.PROTECT,
        sa = TipWords("الذهب في مصر: صناديق مرخصة لا أشخاص وصفحات", "في مصر تشرف الهيئة العامة للرقابة المالية على صناديق الاستثمار في الذهب لا على بيعه المباشر، فأي محل أو صفحة أو تطبيق يبيع الذهب ويدّعي ترخيصها علامة تحذير يمكن الإبلاغ عنها، ولا تودع أموالك لدى شخص أو صفحة تعرض استثمارها لك في الذهب. وإن اشتريت ذهبًا مباشرة فاحتفظ بالمعدن في حيازتك. أما التعامل في العملات المشفرة أو الترويج لها دون ترخيص فيعاقب عليه القانون المصري بالحبس أو الغرامة.", "الذهب والعملات المشفرة من أشهر وسائل التحوط من ضعف الجنيه، ويستغل المحتالون هذه الكلمات واسم الهيئة ليبدوا موثوقين، ومعرفة نطاق إشرافها بدقة تُسقط كثيرًا من الفخاخ."),
        eg = TipWords("الدهب في مصر: صناديق مرخّصة، مش أشخاص وصفحات", "في مصر، الهيئة العامة للرقابة المالية بتشرف على صناديق الاستثمار في الدهب، مش على بيع الدهب المباشر. فأي محل أو صفحة أو تطبيق بيبيع دهب ويقول إنه مرخّص منها يبقى إشارة خطر وتقدر تبلّغ عنه، وعمرك ما تسيب فلوس مع شخص أو صفحة بتعرض تشغّلهالك في الدهب. ولو اشتريت دهب مباشرة، خلّي المعدن في إيدك. والتعامل في العملات المشفرة أو الترويج ليها من غير تصريح عقوبته في مصر حبس أو غرامة.", "الدهب والعملات المشفرة من أشهر طرق الهروب من ضعف الجنيه، والنصابين بيستخدموا نفس الكلام واسم الهيئة عشان يبانوا آمنين. لما تعرف الهيئة بتغطي إيه بالظبط بتكشف فخاخ كتير."),
        source = TipSource("الهيئة العامة للرقابة المالية بمصر: الهيئة تنظم وثائق صناديق الاستثمار في الذهب لا التعامل المباشر فيه (مايو 2025)", "https://fra.gov.eg/en/fra_news/%D8%A7%D9%84%D8%B1%D9%82%D8%A7%D8%A8%D8%A9-%D8%A7%D9%84%D9%85%D8%A7%D9%84%D9%8A%D8%A9-%D8%AA%D8%A4%D9%83%D8%AF-%D8%A3%D9%86%D9%87%D8%A7-%D8%AA%D9%86%D8%B8%D9%85-%D8%A7%D9%84%D8%A7%D8%B3%D8%AA%D8%AB/", "2026-10-16"),
    ),
    BankTip(
        "diversify-savings", "both", "medium", TipGroup.SPREAD,
        sa = TipWords("لا تضع كل مدخراتك في سلة واحدة", "تجنّب إبقاء مدخراتك كلها في شيء واحد، سواء كانت كلها بعملة بلدك أو بعملة أجنبية واحدة أو ذهبًا أو أسهمًا. وزّعها على أصناف مباحة مختلفة كالنقد والأسهم المفحوصة والصكوك والذهب، ونوّع كذلك داخل كل صنف؛ فهذا يحدّ من الضرر عند هبوط أحدها بشدة، ويقيك من نقل كل شيء في لحظة ذعر بعد قفزة كبيرة في سعر الصرف.", "يعتمد التوزيع المناسب على المدة التي تستطيع ترك المال فيها وعلى قدر الخسارة التي تحتملها. وقد أضرت تقلبات العملة والذهب في مصر بمن احتفظ بنوع واحد، ونقل كل شيء بعد القفزة كثيرًا ما يثبّت الخسارة."),
        eg = TipWords("ما تحطش كل مدخراتك في سلة واحدة", "بلاش تخلّي كل مدخراتك في حاجة واحدة، سواء كلها جنيه أو كلها عملة أجنبية واحدة أو كلها دهب أو كلها أسهم. وزّعها على أنواع حلال مختلفة، زي كاش وأسهم مفحوصة وصكوك ودهب، ووزّع كمان جوه كل نوع. التوزيع ده بيقلل الضرر لما واحدة منهم تنزل جامد، وبيحميك إنك تنقل كل حاجة في لحظة خوف بعد قفزة كبيرة في سعر العملة.", "التوزيع المناسب بيعتمد على المدة اللي تقدر تسيب فيها الفلوس وعلى الخسارة اللي تستحملها. وتقلبات العملة والدهب في مصر ضرّت اللي كانوا شايلين نوع واحد بس، ونقل كل حاجة بعد القفزة غالبًا بيثبّت الخسارة."),
        source = TipSource("هيئة الأوراق المالية والبورصات الأمريكية، موقع توعية المستثمر: توزيع الأصول والتنويع", "https://www.investor.gov/introduction-investing/getting-started/asset-allocation", "2026-10-16"),
    ),
    BankTip(
        "verify-sharia-approval", "eg", "medium", TipGroup.HALAL,
        sa = TipWords("تحقق من أن المنتج «الإسلامي» معتمد شرعيًا فعلًا", "إذا أردت خيارات متوافقة مع الشريعة من القطاع المالي غير المصرفي في مصر، فتحقق من أن المنتج مرّ بمنظومة الرقابة الشرعية لدى الهيئة العامة للرقابة المالية، لا مجرد إعلان يصفه بأنه «إسلامي». ويشمل ذلك الصكوك وصناديق الاستثمار الإسلامية وعقود التمويل بالمرابحة.", "تُسوّق منتجات كثيرة على أنها حلال، ووجود مسار اعتماد معروف يتيح لك التحقق بنفسك بدل الاعتماد على الإعلان."),
        eg = TipWords("اتأكد إن المنتج «الإسلامي» معتمد شرعيًا فعلًا", "لو عايز اختيارات متوافقة مع الشريعة من القطاع المالي غير المصرفي في مصر، اتأكد إن المنتج عدّى على منظومة الرقابة الشرعية في الهيئة العامة للرقابة المالية، مش مجرد إعلان مكتوب فيه «إسلامي». ده يشمل الصكوك وصناديق الاستثمار الإسلامية وعقود التمويل بالمرابحة.", "منتجات كتير بتتسوّق على إنها حلال، ووجود طريق اعتماد معروف بيخليك تتأكد بنفسك بدل ما تصدّق الإعلان."),
        source = TipSource("الهيئة العامة للرقابة المالية في مصر — اللجنة المركزية للرقابة الشرعية", "https://fra.gov.eg/en/%D9%82%D8%B1%D8%A7%D8%B1%D8%A7%D8%AA-%D9%84%D8%AC%D9%86%D8%A9-%D8%A7%D9%84%D8%B1%D9%82%D8%A7%D8%A8%D9%87-%D8%A7%D9%84%D8%B4%D8%B1%D8%B9%D9%8A%D8%A9-%D8%A7%D9%84%D9%85%D8%B1%D9%83%D8%B2%D9%8A%D8%A9/", "2026-10-16"),
    ),
    BankTip(
        "licensed-remittance-sa", "sa", "high", TipGroup.PROTECT,
        sa = TipWords("حوّل أموالك عبر جهة مرخّصة فقط", "عند تحويل المال إلى بلدك من المملكة، استخدم بنكًا أو شركة تحويل مرخّصة من البنك المركزي السعودي، وتحقّق من اسمها في قائمة الجهات المرخّصة على موقعه الرسمي قبل التعامل. وتجنّب من يتواصل معك عبر واتساب أو تيليجرام، أو يعرض سعرًا مغريًا أو عائدًا مضمونًا، أو يستعجلك في القرار، أو يستخدم اسمًا قريبًا من اسم بنك معروف.", "يُعدّ المقيمون الذين يحوّلون شهريًا هدفًا شائعًا للصرّافين غير المرخّصين وخدمات التحويل الوهمية."),
        eg = TipWords("حوّل فلوسك من جهة مرخّصة بس", "لما تبعت فلوس لأهلك من السعودية، استخدم بنك أو شركة تحويل مرخّصة من البنك المركزي السعودي، واتأكد من اسمها في قايمة الجهات المرخّصة على موقعه قبل ما تتعامل. ابعد عن أي حد يكلمك على واتساب أو تيليجرام، أو يوعدك بسعر مميز أو مكسب مضمون، أو يستعجلك تقرر، أو اسمه شبه اسم بنك معروف.", "اللي بيحوّلوا كل شهر هدف سهل للصرّافين غير المرخّصين وشركات التحويل الوهمية."),
        source = TipSource("البنك المركزي السعودي — الأنشطة غير المرخّصة", "https://www.sama.gov.sa/en-US/Supervision/Pages/unlicensed_activities.aspx", "2026-10-16"),
    ),
    BankTip(
        "receive-in-eg-bank", "eg", "medium", TipGroup.PROTECT,
        sa = TipWords("استلم الحوالة في مصر على حساب بنكي", "اجعل الحوالة تصل إلى حساب بنكي في مصر عبر قناة رسمية؛ فقد رخّص البنك المركزي المصري لعدد من البنوك بإضافة الحوالات الواردة من الخارج إلى الحساب فورًا وفي أي وقت، متى جاءت عبر بنوك مراسلة وشركات صرافة مرخّصة في الخارج. وتجنّب تجار العملة غير الرسميين الذين يعدون بسعر أفضل.", "توثّق القناة الرسمية كل حوالة وتجنّبك المخاطر القانونية والاحتيال المرتبطة بالتعامل غير الرسمي بالعملة. والخبر منشور في ديسمبر 2024، فتحقّق من البنوك التي تقدّم الخدمة حاليًا."),
        eg = TipWords("استلم في مصر على حساب بنكي", "خلّي الفلوس توصل مصر على حساب بنكي من قناة رسمية. البنك المركزي المصري رخّص لبنوك تضيف الحوالات الجاية من برّه على الحساب فورًا وفي أي وقت، لو جاية عن طريق بنوك مراسلة وشركات صرافة مرخّصة برّه. وابعد عن تجار العملة «إيد بإيد» اللي بيوعدوك بسعر أحسن.", "القناة الرسمية بتسيب أثر لكل تحويلة وبتبعدك عن مشاكل القانون والنصب. الخبر من ديسمبر 2024، فاسأل بنكك هل الخدمة متاحة عنده."),
        source = TipSource("البنك المركزي المصري — إتاحة الحوالات الواردة على حسابات العملاء لحظيًا (5 ديسمبر 2024)", "https://www.cbe.org.eg/en/news-publications/news/2024/12/05/11/18/availing-inbound-remittances-to-customers-bank-accounts-instantly", "2026-10-16"),
    ),
    BankTip(
        "gosi-no-pension-expat", "sa", "medium", TipGroup.START,
        sa = TipWords("عملك في المملكة لا يبني لك معاشًا تقاعديًا", "فرع المعاشات في المؤسسة العامة للتأمينات الاجتماعية مقصور على السعوديين، أما العامل غير السعودي فيغطيه فرع الأخطار المهنية فقط. لذلك لا يبني لك عملك في المملكة معاشًا تقاعديًا، فخطّط لادخار طويل الأجل لتقاعدك ولا تعتمد على معاش سعودي.", "يظن كثير من المقيمين أن تسجيلهم في التأمينات يعني معاشًا تقاعديًا، وهو ليس كذلك لغير السعوديين."),
        eg = TipWords("شغلك في السعودية مش بيعملك معاش", "فرع المعاشات في التأمينات الاجتماعية السعودية للسعوديين بس. لو انت مش سعودي، التغطية عندك لإصابات العمل بس، يعني شغلك هناك مش بيبنيلك معاش. خطّط لادخار طويل لتقاعدك بنفسك وما تعتمدش على معاش سعودي.", "ناس كتير فاكرة إن تسجيلهم في التأمينات معناه معاش، وده مش صح لغير السعوديين."),
        source = TipSource("المؤسسة العامة للتأمينات الاجتماعية — صفحة التسجيل", "https://www.gosi.gov.sa/GOSIOnline/Registration&locale=en_US", "2026-10-16"),
