    BankTip(
        "nosi-egyptians-abroad", "eg", "low", TipGroup.START,
        sa = TipWords("تأمين اجتماعي مصري للعاملين في الخارج", "يستطيع المصري العامل في الخارج الاشتراك اختياريًا في التأمين الاجتماعي المصري عبر الهيئة القومية للتأمين الاجتماعي، فيختار شريحة دخل تناسب دخله، ويهدف النظام إلى توفير معاش له ولأسرته لاحقًا. ويلزم إثبات العمل في الخارج كعقد موثّق، مع مستندات الهوية وتقرير طبي. راجع جدول الشرائح المعمول به قبل الاشتراك.", "يسدّ هذا فجوة المعاش في المملكة. وتحيل الصفحة إلى جدول شرائح صادر عام 2023، فقد تكون المبالغ تغيّرت."),
        eg = TipWords("فيه تأمين اجتماعي مصري للي شغالين برّه", "المصري اللي شغال برّه يقدر يشترك اختياري في التأمينات الاجتماعية المصرية عن طريق الهيئة القومية للتأمين الاجتماعي. بتختار شريحة دخل تناسب دخلك، والهدف معاش ليك ولأسرتك بعدين. هتحتاج إثبات شغل برّه زي عقد موثّق، وورق إثبات الشخصية، وتقرير طبي. راجع جدول الشرايح الحالي قبل ما تشترك.", "ده بيسد فجوة المعاش اللي في السعودية. الصفحة بتحيل لجدول شرايح من 2023، فالمبالغ ممكن تكون اتغيرت."),
        source = TipSource("الهيئة القومية للتأمين الاجتماعي (مصر) — التأمين على المصريين العاملين بالخارج", "https://www.nosi.gov.eg/ar/Services/Pages/Info/WorkingAbroad.aspx", "2026-10-16"),
