    BankTip(
        "budget-remittance-commitment", "both", "none", TipGroup.START,
        sa = TipWords("أدرج مبلغ التحويل للأهل في ميزانيتك", "دوّن دخلك وجميع التزاماتك الشهرية الثابتة، واعدُد المبلغ الذي ترسله لأهلك أحد هذه الالتزامات لا ما يتبقّى آخر الشهر. فالميزانية الواضحة تبيّن المساحة الحقيقية المتاحة للادخار والاستثمار بعد نفقات المعيشة والتحويلات.", "حين يكون التحويل هو «المتبقّي» يضطرب كل شهر، ولا تتضح قدرتك الحقيقية على الادخار."),
        eg = TipWords("حط تحويلة أهلك في الميزانية", "اكتب دخلك وكل التزاماتك الثابتة كل شهر، واعتبر المبلغ اللي بتبعته لأهلك التزام منهم، مش «اللي يفضل». الميزانية الواضحة بتوريك قد إيه فاضلك فعلًا للادخار والاستثمار بعد المعيشة والتحويل.", "لما التحويلة تبقى «الباقي» بتتلخبط كل شهر، ومش بتعرف قدرتك الحقيقية على الادخار."),
        source = TipSource("موقع تثقيف المستثمرين التابع لهيئة الأوراق المالية الأمريكية — بناء الثروة بالادخار والاستثمار", "https://www.investor.gov/build-wealth-over-time-through-saving-and-investing", "2026-10-16"),
