    BankTip(
        "two-currencies-fx-risk", "both", "medium", TipGroup.SPREAD,
        sa = TipWords("مدخراتك بعملتين تتأثر بسعر الصرف", "إذا كانت مدخراتك بالريال والجنيه المصري، فتذكّر أن تغيّر سعر الصرف قد يرفع قيمة أموالك عند التحويل أو يخفضها حتى لو لم يتغيّر الرصيد. وقد تقيّد بعض الدول خروج الأموال منها أو تؤخّره. تابع كل عملة على حدة، ولا تفترض ثبات سعر اليوم.", "ما دامت أموالك في بلدين فمخاطر العملة جزء من وضعك، وهذا تثقيف عام لا توصية بعملة بعينها."),
        eg = TipWords("فلوسك بعملتين بتتأثر بسعر الصرف", "لو مدّخر بالريال والجنيه، افتكر إن تغيّر سعر الصرف ممكن يزوّد أو يقلّل قيمة فلوسك وقت التحويل حتى لو الرصيد زي ما هو. وفيه دول ممكن تحدّ أو تأخّر خروج الفلوس منها. تابع كل عملة لوحدها وما تفترضش إن سعر النهارده هيفضل ثابت.", "طالما فلوسك في بلدين، خطر العملة جزء من وضعك. ده تثقيف مش ترشيح لعملة معيّنة."),
