    BankTip(
        "avoid-riba-savings-loans", "both", "low", TipGroup.HALAL,
        sa = TipWords("تجنّب الادخار والاقتراض القائمين على الفائدة", "الفائدة المشروطة في عقد القرض، والزيادة على الدين الحالّ مقابل الإمهال، من الربا المحرّم. فلا تقترض بفائدة، ولا تُبقِ في بطاقتك الائتمانية رصيدًا تُحتسب عليه فائدة، لتحويل المال إلى أهلك أو لسدّ عجز. وعند الادخار اسأل بنكك عن بدائل متوافقة مع الشريعة بدل الودائع والشهادات ذات الفائدة الثابتة، وتحقّق من طريقة تحقيق عائدها.", "تُسوَّق الشهادات مرتفعة الفائدة للمغتربين بكثافة، ويسهل الحصول على البطاقات الائتمانية في المملكة. وهذه النصيحة تحذّر دون تسمية منتج بعينه."),
        eg = TipWords("ابعد عن الادخار والقروض اللي بفايدة", "الفايدة المشروطة على القرض، والزيادة على دين متأخر مقابل المهلة، ربا. فما تستلفش بفايدة، ولا تسيب رصيد بطاقة يتحسب عليه فايدة، عشان تبعت لأهلك أو تسد عجز. ولو هتدّخر، اسأل بنكك عن بدائل متوافقة مع الشريعة بدل الودايع والشهادات بفايدة ثابتة، واتأكد الربح بييجي منين.", "الشهادات بفايدة عالية بتتسوّق كتير للمغتربين، والبطاقات الائتمانية سهل تطلعها في السعودية. النصيحة دي بتحذّر من غير ما تسمّي منتج."),
        source = TipSource("مجمع الفقه الإسلامي الدولي — القرار رقم 10 (10/2) بشأن حكم التعامل المصرفي بالفوائد والتعامل بالمصارف الإسلامية", "https://iifa-aifi.org/en/32234.html", "2026-10-16"),
    ),
    BankTip(
        "irregular-income-fixed-salary", "both", "none", TipGroup.START,
        sa = TipWords("ابنِ ميزانيتك على أدنى دخل، وادفع لنفسك راتبًا ثابتًا", "إذا كان دخلك يتغيّر من شهر لآخر، فابنِ ميزانيتك على أدنى دخل يمكنك الاعتماد عليه، لا على المتوسط ولا على أفضل الشهور. اجعل مدفوعات العملاء كلها تصب في حساب دخل واحد، وحوّل منه راتبًا ثابتًا إلى حساب الإنفاق كل شهر، مبتدئًا بالضروريات. وما يزيد على الأساس يذهب إلى الادخار أو أهدافك.", "الميزانية المبنية على شهر جيد تنهار في أول شهر ضعيف، والراتب الثابت من حساب الدخل يجعل الدخل غير المنتظم يسير كالراتب المنتظم."),
        eg = TipWords("اعمل ميزانيتك على أقل شهر، وادفع لنفسك مرتب ثابت", "لو دخلك بيتغير من شهر للتاني، ابني الميزانية على أقل دخل تقدر تعتمد عليه، مش المتوسط ولا أحسن شهر. خلّي كل فلوس العملاء تنزل في حساب دخل واحد، وحوّل منه نفس المرتب الثابت لحساب مصروفك كل شهر، وابدأ بالأساسيات. واللي يزيد عن الأساس اعتبره زيادة تروح للادخار أو لأهدافك.", "الميزانية المبنية على شهر حلو بتقع في أول شهر واقف. والمرتب الثابت من حساب الدخل بيخلّي الدخل المتقطع يمشي زي المرتب."),
        source = TipSource("إدارة البنوك والتمويل بولاية نبراسكا (جهة رقابية مالية أمريكية) — الميزانية مع الدخل غير المنتظم", "https://ndbf.nebraska.gov/how-budget-effectively-irregular-income", "2026-10-16"),
