    BankTip(
        "gosi-voluntary-pension-saudi", "sa", "none", TipGroup.START,
        sa = TipWords("لا صاحب عمل يعني لا معاش تلقائيًا: تعرّف على الاشتراك الاختياري", "إذا كنت تعمل لحسابك فلن يسجّلك أحد في المعاش تلقائيًا. ويحق للسعودي العامل في مهنة حرة أو صاحب النشاط الخاص الاشتراك اختياريًا في فرع المعاشات لدى المؤسسة العامة للتأمينات الاجتماعية، فيختار فئة الأجر ويتحمّل الاشتراك كاملًا. اختر مستوى تستطيع الاستمرار فيه في الشهور الضعيفة، وعامله فاتورة شهرية ثابتة في ميزانيتك.", "كثير من العاملين لحسابهم يبلغون سن التقاعد بلا معاش لأن أحدًا لم يقتطعه لهم."),
        eg = TipWords("مفيش صاحب شغل يعني مفيش معاش تلقائي: اعرف الاشتراك الاختياري", "لو شغال لحسابك، محدش هيسجّلك في معاش لوحده. السعودي اللي بيشتغل في مهنة حرة أو عنده نشاط خاص يقدر يشترك اختياري في فرع المعاشات في التأمينات الاجتماعية: بيختار فئة اشتراك ويدفع الاشتراك كله بنفسه. اختار مستوى تقدر تكمّل تدفعه في الشهور الواقفة، واعتبره فاتورة ثابتة في ميزانيتك.", "اللي بيشتغلوا لحسابهم كتير بيوصلوا سن المعاش من غير معاش، عشان محدش كان بيستقطع لهم."),
        source = TipSource("المؤسسة العامة للتأمينات الاجتماعية — صفحة نظام التأمينات الاجتماعية", "https://beta.gosi.gov.sa/en/social-insurance", "2026-10-16"),
    ),
    BankTip(
        "nosi-irregular-employment", "eg", "none", TipGroup.START,
        sa = TipWords("اعرف فئتك في التأمين الاجتماعي بمصر", "يمكن للعاملين بصورة غير منتظمة في مصر الحصول على تغطية تأمينية، ومن ذلك فئة العمالة غير المنتظمة التي يُسجَّل فيها بتقديم استمارة 1 مع صورتي بطاقة الرقم القومي وشهادة الميلاد إلى مكتب التأمينات التابع لمحل النشاط. ولأصحاب الأعمال الخاصة فئة أخرى. استفسر من مكتب التأمينات عن الفئة المناسبة لعملك وسجّل، فالمعاش لا يأتي تلقائيًا.", "تبني الاشتراكات معاشًا وحمايات أخرى، ومن لا يسجّل لا ينال منها شيئًا."),
        eg = TipWords("اعرف فئتك في التأمينات الاجتماعية في مصر", "اللي شغلهم مش منتظم في مصر يقدروا ياخدوا تغطية تأمينية. من الطرق فئة العمالة غير المنتظمة، والتسجيل فيها بتقديم استمارة 1 مع صورة البطاقة وشهادة الميلاد في مكتب التأمينات التابع لمكان شغلك. واللي عنده نشاط خاص ليه فئة تانية لأصحاب الأعمال. اسأل مكتب التأمينات إيه الفئة اللي تناسبك وسجّل، لأن المعاش مش بييجي لوحده.", "الاشتراكات بتبني معاش وحماية تانية، واللي ما بيسجّلش ما بياخدش منها حاجة."),
        source = TipSource("الهيئة القومية للتأمين الاجتماعي (مصر) — خدمة التأمين على العمالة غير المنتظمة", "https://www.nosi.gov.eg/ar/Services/Pages/Info/Informalemployment.aspx", "2026-10-16"),
    ),
    BankTip(
        "vat-threshold-saudi", "sa", "none", TipGroup.START,
        sa = TipWords("تابع مجموع مبيعاتك الخاضعة للضريبة خلال 12 شهرًا", "احتفظ بمجموع متجدد لمبيعاتك الخاضعة للضريبة من عملك الحر خلال الاثني عشر شهرًا الماضية؛ ففي المملكة يصبح التسجيل في ضريبة القيمة المضافة إلزاميًا إذا تجاوز هذا المجموع 375,000 ريال، ويجوز للمقيم التسجيل اختياريًا إذا تجاوز 187,500 ريال. ويُنبّهك هذا المجموع مسبقًا عند اقترابك من الحد.", "مع الدخل غير المنتظم قد تتجاوز الحدّ ببضعة عقود كبيرة دون أن تنتبه."),
        eg = TipWords("راقب مجموع مبيعاتك في 12 شهر عشان ضريبة القيمة المضافة", "خلّي معاك مجموع متجدد لمبيعاتك الخاضعة للضريبة من شغلك الحر في آخر 12 شهر. في السعودية التسجيل في ضريبة القيمة المضافة بيبقى إجباري لما المجموع ده يعدّي 375,000 ريال، ومسموح تسجّل اختياري لو عدّى 187,500 ريال. المجموع ده بينبّهك قبلها إنك قرّبت.", "مع الدخل المتقطع، كام عقد كبير ممكن يعدّوك الحد من غير ما تاخد بالك."),
        source = TipSource("هيئة الزكاة والضريبة والجمارك — دليل الخدمات المهنية في ضريبة القيمة المضافة (الإصدار الثالث، مايو 2026)", "https://zatca.gov.sa/en/HelpCenter/guidelines/Documents/Guideline-on-Professional-Services-under-VAT-Provisions.pdf", "2026-10-16"),
    ),
    BankTip(
        "fake-gigs-upfront-fees", "both", "high", TipGroup.PROTECT,
        sa = TipWords("احذر الأعمال الوهمية: العميل الحقيقي لا يطلب منك الدفع أولًا", "كن حذرًا من أي عمل أو عمل جانبي يطلب منك دفع رسوم تدريب أو معدات أو «رسوم بدء»، أو يعد بأجر كبير مقابل جهد قليل، أو يضغط عليك للقبول فورًا. وقبل الموافقة ابحث عن الشركة بنفسك واسأل من عملوا معها.", "الباحثون عن دخل إضافي هدف رئيسي لهذا النوع من الاحتيال، والمال المدفوع مقدّمًا يضيع غالبًا."),
        eg = TipWords("الشغلانة الوهمية: العميل الحقيقي عمره ما يطلب منك تدفع الأول", "شُك في أي شغلانة أو شغل جانبي يطلب منك تدفع تمن تدريب أو معدات أو «رسوم بداية»، أو يوعدك بفلوس كتير على شغل قليل، أو يزنقك تقبل حالًا. قبل ما توافق، دوّر على الشركة بنفسك واسأل ناس اشتغلوا معاها.", "اللي بيدوّروا على شغل زيادة هدف أساسي للنصب ده، والفلوس اللي بتتدفع مقدّم غالبًا بتضيع."),
        source = TipSource("لجنة التجارة الاتحادية الأمريكية — تنبيه للمستهلكين عن احتيال الأعمال الجانبية (24 فبراير 2026)", "https://consumer.ftc.gov/consumer-alerts/2026/02/how-avoid-side-hustle-scam", "2026-10-16"),
